if(!defined('ABSPATH')){exit;} final class DSVS_Leagues { private static $leagues=array('OL'=>array('name'=>'Oberliga','id'=>86),'A'=>array('name'=>'A-Liga','id'=>87),'B'=>array('name'=>'B-Liga','id'=>88),'C1'=>array('name'=>'C1-Liga','id'=>90),'C2'=>array('name'=>'C2-Liga','id'=>92),'LC'=>array('name'=>'Liga Cup','id'=>93),'CLVH'=>array('name'=>'C-Liga Vergleichskampf (Hinrunde)','id'=>96),'CLVR'=>array('name'=>'C-Liga Vergleichskampf (Rückrunde)','id'=>97)); public static function get($key){$key=strtoupper(trim((string)$key));if('AL'===$key){$key='A';}if(!isset(self::$leagues[$key])){return false;}$league=self::$leagues[$key];$league['key']=$key;$league['url']=sprintf('https://dsv-schwaben.de/sb_spielplan.php?p=209--%s-%d',DSVS_Settings::season(),$league['id']);return $league;} }
